-- Create Database
CREATE DATABASE RegionalSales2025;

-- Use Create Database
USE RegionalSales2025;

-- Create Table
CREATE TABLE RegionalSales (
    OrderID VARCHAR(255),
    Date DATE,
    CustomerID VARCHAR(255),
    Region VARCHAR(255),
    ProductName VARCHAR(255),
    Category VARCHAR(255),
    Quantity VARCHAR(255),
    UnitPrice VARCHAR(255),
    TotalAmount VARCHAR(255),
    OrderStatus VARCHAR(255),
    SalesAgent VARCHAR(255)
);

-- Insert Into

-- Monthly trend of sales across all regions
SELECT 
    DATE_FORMAT(Date, '%Y-%m') AS Month,
    Region,
    SUM(TotalAmount) AS MonthlySales
FROM RegionalSales
WHERE OrderStatus = 'Completed'
GROUP BY Month, Region
ORDER BY Month, Region;

-- Percentage of canceled and returned orders per region
SELECT 
    Region,
    ROUND(100.0 * SUM(CASE WHEN OrderStatus = 'Cancelled' THEN 1 ELSE 0 END) / COUNT(*), 2) AS Cancelled_Percentage,
    ROUND(100.0 * SUM(CASE WHEN OrderStatus = 'Returned' THEN 1 ELSE 0 END) / COUNT(*), 2) AS Returned_Percentage
FROM RegionalSales
GROUP BY Region;

-- Identify 3 regions/products with most revenue loss (cancelled/returned).
SELECT 
    Region,
    ProductName,
    SUM(TotalAmount) AS RevenueLoss
FROM RegionalSales
WHERE OrderStatus IN ('Cancelled', 'Returned')
GROUP BY Region, ProductName
ORDER BY RevenueLoss DESC
LIMIT 3;

-- Average order value by product category 
SELECT 
    Category,
    ROUND(AVG(TotalAmount), 2) AS AvgOrderValue
FROM RegionalSales
WHERE OrderStatus = 'Completed'
GROUP BY Category
ORDER BY AvgOrderValue DESC;

-- Top 5 performing sales agents (by completed revenue)
SELECT 
    SalesAgent,
    SUM(TotalAmount) AS CompletedRevenue
FROM RegionalSales
WHERE OrderStatus = 'Completed'
GROUP BY SalesAgent
ORDER BY CompletedRevenue DESC
LIMIT 5;

-- Category-wise total sales and contribution to grand total
SELECT 
    Category,
    SUM(TotalAmount) AS CategorySales,
    ROUND(100.0 * SUM(TotalAmount) / 
        (SELECT SUM(TotalAmount) FROM RegionalSales WHERE OrderStatus='Completed'), 2
    ) AS Contribution_Percentage
FROM RegionalSales
WHERE OrderStatus = 'Completed'
GROUP BY Category
ORDER BY CategorySales DESC;

-- List customers with highest frequency of returns (>=3 times)
SELECT 
    CustomerID,
    COUNT(*) AS ReturnCount
FROM RegionalSales
WHERE OrderStatus = 'Returned'
GROUP BY CustomerID
HAVING COUNT(*) >= 3
ORDER BY ReturnCount DESC;